import java.util.*;

class Employee {
    String name;
    Employee(String name) { this.name = name; }
    int bonus() { return 200; }
}
class Manager extends Employee {
    Manager(String name) { super(name); }
    @Override int bonus() { return 500; }
}
public class Main {
    public static void main(String[] args) {
        List<Employee> staff = new ArrayList<>();
        staff.add(new Employee("Sam"));
        staff.add(new Manager("Rae"));
        for (Employee e : staff) System.out.println(e.name + " " + e.bonus());
    }
}

class Notification {
    String send() { return "ping"; }
}
class UrgentNotification extends Notification {
    @Override
    String send() { return "ALERT"; }
}
public class Main {
    static void notify(Notification n) {
        System.out.println(n.send());
    }
    public static void main(String[] args) {
        Notification[] queue = { new Notification(), new UrgentNotification() };
        for (Notification n : queue) notify(n);
    }
}

interface Sound { void play(); }
class Beep implements Sound { public void play() { System.out.println("beep"); } }
class Chime implements Sound { public void play() { System.out.println("chime"); } }
class Alarm {
  Sound sound;
  Alarm(Sound sound) { this.sound = sound; }
  void ring() { sound.play(); }
}

interface Greeting { String say(String name); }
class Formal implements Greeting {
  public String say(String name) { return "Good day, " + name; }
}
class Casual implements Greeting {
  public String say(String name) { return "Hey " + name; }
}
class Host {
  Greeting style;
  Host(Greeting style) { this.style = style; }
  void greet(String name) { System.out.println(style.say(name)); }
}
public class Main {
  public static void main(String[] args) {
    Host desk = new Host(new Formal());
    desk.greet("Ana");
    Host desk2 = new Host(new Casual());
    desk2.greet("Ana");
  }
}

interface Channel { String send(String msg); }
class Email implements Channel {
  public String send(String msg) { return "EMAIL:" + msg; }
}
class Sms implements Channel {
  public String send(String msg) { return "SMS:" + msg; }
}
class Notifier {
  Channel channel;
  Notifier(Channel channel) { this.channel = channel; }
  void alert(String msg) { System.out.println(channel.send(msg)); }
}
public class Main {
  public static void main(String[] args) {
    Notifier n = new Notifier(new Sms());
    n.alert("late");
    n = new Notifier(new Email());
    n.alert("late");
  }
}
